assert len(ITEMS) == 19, len(ITEMS)
for i, it in enumerate(ITEMS):
    for ch in ('\n', '\r', '\t'):
        assert ch not in it, '第 %d 段含控制字符' % (i + 1)
    assert it.strip() == it and it, '第 %d 段首尾空白或空' % (i + 1)

joined = '\n'.join(ITEMS)
for m in ('老福特', '楼中楼', '文风', '滑窗', '真源', '单套件'):
    assert m in joined, '缺 marker：' + m
assert joined.count('本版') > 10

